Unit Test Code:
#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_slice_valid_range_no_special_cases(void) {
    // Setup: create a buffer with known data
    buffer_t *src = helper_make_buffer_with_data("abcdef");
    TEST_ASSERT_NOT_NULL(src);

    // Choose from and to such that:
    // - to >= from
    // - to >= 0
    // - to <= len
    // - no capping, no negative to, no early return
    // For "abcdef" (len=6), from=2, to=5 yields "cde"
    size_t from = 2;
    ssize_t to = 5;

    // Test: call buffer_slice
    buffer_t *slice = buffer_slice(src, from, to);

    // Assertions
    TEST_ASSERT_NOT_NULL(slice);
    helper_assert_buffer_data_equals(slice, "cde");
    helper_assert_buffer_length(slice, 3);

    // Cleanup
    buffer_free(src);
    buffer_free(slice);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_slice_valid_range_no_special_cases);
    return UNITY_END();
}

